-- Weekly Arena 2026-W48: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W48', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-11-23T00:00:00.000Z', '2026-11-30T00:00:00.000Z', 60, 'published', $WK86275ccc780e$[{"id":"wk-2026-w48-01-4968","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $34$ and $18$ and each non-parallel side has length $17$. Find its area.","type":"text","correctAnswer":"390","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $8$ and hypotenuse $17$.","solution":"The height is $\\sqrt{17^2-8^2}=15$, so the area is $\\tfrac12(34+18)(15)=390$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w48-02-e485","title":"No Neighbouring Ones","topic":"Combinatorics","level":"Intermediate","question":"How many binary strings of length $9$ contain no two consecutive $1$s?","type":"text","correctAnswer":"89","hint":"Condition on the last digit to get a Fibonacci-type recurrence.","solution":"Let $f(n)=f(n-1)+f(n-2)$ with $f(1)=2$, $f(2)=3$; then $f(9)=89$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-03-6a7f","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 3 \\pmod{7}$, $n\\equiv 1 \\pmod{5}$, $n\\equiv 12 \\pmod{13}$.","type":"text","correctAnswer":"311","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $311$ modulo $455$, and $311$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-04-01c0","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $304$ that are divisible by $5$ or by $12$ (or both).","type":"text","correctAnswer":"12150","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $5$, $12$ and $60$ gives $12150$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2026-w48-05-330f","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $20$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"800","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=20$, i.e. $800$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-06-37ec","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{38} \\left\\lfloor \\frac{8k}{13} \\right\\rfloor$.","type":"text","correctAnswer":"438","hint":"Write $8k=13q+r$ and track how the remainder cycles with period $13$.","solution":"Evaluating each floor term and adding gives $438$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-07-28b6","title":"The Last Three Digits","topic":"Number Theory","level":"Advanced","question":"Find the remainder when $71^{301}$ is divided by $1000$.","type":"text","correctAnswer":"71","hint":"Work modulo $8$ and modulo $125$ separately and combine, or use the order of the unit in $(\\mathbb Z/1000)^\\times$.","solution":"Modular exponentiation gives $71^{301}\\equiv 71 \\pmod{1000}$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-08-5e1a","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 7t + 4 = 0$. Find the remainder when $r^{8} + s^{8}$ is divided by $1000$.","type":"text","correctAnswer":"689","hint":"Let $S_k=r^k+s^k$. Then $S_k=7S_{k-1}-4S_{k-2}$, with $S_0=2$, $S_1=7$.","solution":"Using $S_k=7S_{k-1}-4S_{k-2}$ from $S_0=2$, $S_1=7$ gives $S_{8}=2718689$, whose remainder modulo $1000$ is $689$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-09-b544","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(11,8)$ and $(10,11)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"20","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $41$ and the boundary has $B=3$ lattice points, so $I=(41-3+2)/2=20$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-10-5898","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 5-tuples $(x_1,\\dots,x_5)$ of non-negative integers satisfy $x_1+\\cdots+x_5=16$ with every $x_i\\le 4$?","type":"text","correctAnswer":"70","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $70$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28}]$WK86275ccc780e$::jsonb
where not exists (select 1 from public.arenas where title = 'Weekly Arena 2026-W48');
